return function(Plasma)
	local create = Plasma.create
	return Plasma.widget(function(text, options)
		options = options or {}
		local refs = Plasma.useInstance(function(ref)
			local style = Plasma.useStyle()
			local label = create("TextBox", {
				TextSize = 22,
				AutomaticSize = Enum.AutomaticSize.XY,
				Text = text,
				BackgroundTransparency = 0,
				BackgroundColor3 = style.bg2,
				TextColor3 = Color3.new(1, 1, 1),
				Font = Enum.Font.GothamBold,
				TextEditable = false,
				create("UIPadding", {
					PaddingTop = UDim.new(0, 8),
					PaddingBottom = UDim.new(0, 8),
					PaddingLeft = UDim.new(0, 8),
					PaddingRight = UDim.new(0, 8),
				}),
				create("UICorner")
			})
			
			ref.label = label
			return label
		end)
		refs.label.Text = text
		refs.label.Size = options.Size or UDim2.fromScale(0, 0)
		refs.label.TextXAlignment = options.TextXAlignment or Enum.TextXAlignment.Center
		refs.label.AutomaticSize = options.AutomaticSize or Enum.AutomaticSize.XY
		refs.label.TextWrapped = options.TextWrapped or false
		return refs.label
	end)
end
